 clyde:{n:[`克莱德·巴尼特`,`Clyde Barnett`,`Clyde Barnett`],s:[`老克莱德`,`Clyde`,`Clyde`],p:[`他`,`him`,`ele`],role:[`沃思堡牛仔竞技场的老播音员`,`Old announcer at the Cowtown Coliseum`,`Velho locutor do Cowtown Coliseum`],loc:'fortworth'}
